=== FILE: axi4_lite_regs.v ===
`timescale 1ns / 1ps
`default_nettype none

// axi4_lite_regs
//
// Four 32-bit read/write registers behind an AXI4-Lite subordinate port.
// Interface:          interface_spec.md
// Implementation plan: microarchitecture.md
// Requirement:        req-df40b5a460 (Create an AXI4-Lite register block)
//
// - READY is a function of state only (microarchitecture.md section 1).
// - AW and W are captured in holding registers and paired by do_write,
//   which covers AW first, W first and both together (section 2).
// - Registers are four separate flops, updated byte by byte by WSTRB (section 3).
// - Unmapped (misaligned) addresses answer SLVERR and change nothing (section 4).
// - B and R are registered: 1-cycle latency, held until taken (section 5).
// - aresetn is synchronous and active low (section 6).
module axi4_lite_regs #(
  parameter integer ADDR_WIDTH = 4,
  parameter integer DATA_WIDTH = 32
) (
  input  wire                    aclk,
  input  wire                    aresetn,
  // Write address channel
  input  wire [ADDR_WIDTH-1:0]   s_axil_awaddr,
  input  wire                    s_axil_awvalid,
  output wire                    s_axil_awready,
  // Write data channel
  input  wire [DATA_WIDTH-1:0]   s_axil_wdata,
  input  wire [DATA_WIDTH/8-1:0] s_axil_wstrb,
  input  wire                    s_axil_wvalid,
  output wire                    s_axil_wready,
  // Write response channel
  output wire [1:0]              s_axil_bresp,
  output wire                    s_axil_bvalid,
  input  wire                    s_axil_bready,
  // Read address channel
  input  wire [ADDR_WIDTH-1:0]   s_axil_araddr,
  input  wire                    s_axil_arvalid,
  output wire                    s_axil_arready,
  // Read data channel
  output wire [DATA_WIDTH-1:0]   s_axil_rdata,
  output wire [1:0]              s_axil_rresp,
  output wire                    s_axil_rvalid,
  input  wire                    s_axil_rready
);

  localparam integer STRB_WIDTH  = DATA_WIDTH / 8;
  localparam [1:0]   RESP_OKAY   = 2'b00;
  localparam [1:0]   RESP_SLVERR = 2'b10;

  // ---------------------------------------------------------------------
  // State
  // ---------------------------------------------------------------------
  // Control state and registers: reset (microarchitecture.md section 6).
  reg                  aw_held_q;
  reg                  w_held_q;
  reg                  bvalid_q;
  reg [1:0]            bresp_q;
  reg                  rvalid_q;
  reg [1:0]            rresp_q;
  reg [DATA_WIDTH-1:0] rdata_q;
  reg [DATA_WIDTH-1:0] reg0_q;
  reg [DATA_WIDTH-1:0] reg1_q;
  reg [DATA_WIDTH-1:0] reg2_q;
  reg [DATA_WIDTH-1:0] reg3_q;

  // Holding registers: datapath, not reset (microarchitecture.md section 2).
  // They are read only while the reset-cleared held flag is set.
  reg [ADDR_WIDTH-1:0] aw_addr_q;
  reg [DATA_WIDTH-1:0] w_data_q;
  reg [STRB_WIDTH-1:0] w_strb_q;

  // Next state
  reg                  aw_held_d;
  reg                  w_held_d;
  reg                  bvalid_d;
  reg [1:0]            bresp_d;
  reg                  rvalid_d;
  reg [1:0]            rresp_d;
  reg [DATA_WIDTH-1:0] rdata_d;
  reg [DATA_WIDTH-1:0] reg0_d;
  reg [DATA_WIDTH-1:0] reg1_d;
  reg [DATA_WIDTH-1:0] reg2_d;
  reg [DATA_WIDTH-1:0] reg3_d;

  // ---------------------------------------------------------------------
  // Handshakes: READY from state only
  // ---------------------------------------------------------------------
  assign s_axil_awready = !aw_held_q && !bvalid_q;
  assign s_axil_wready  = !w_held_q && !bvalid_q;
  assign s_axil_arready = !rvalid_q;

  assign s_axil_bvalid  = bvalid_q;
  assign s_axil_bresp   = bresp_q;
  assign s_axil_rvalid  = rvalid_q;
  assign s_axil_rresp   = rresp_q;
  assign s_axil_rdata   = rdata_q;

  wire aw_hs = s_axil_awvalid && s_axil_awready;
  wire w_hs  = s_axil_wvalid && s_axil_wready;
  wire ar_hs = s_axil_arvalid && s_axil_arready;

  // The write fires on the edge that completes the AW/W pair.
  wire do_write = (aw_held_q || aw_hs) && (w_held_q || w_hs);

  // Held copy when one exists, else the live bus.
  wire [ADDR_WIDTH-1:0] wr_addr = aw_held_q ? aw_addr_q : s_axil_awaddr;
  wire [DATA_WIDTH-1:0] wr_data = w_held_q ? w_data_q : s_axil_wdata;
  wire [STRB_WIDTH-1:0] wr_strb = w_held_q ? w_strb_q : s_axil_wstrb;

  // ---------------------------------------------------------------------
  // Address decode (microarchitecture.md section 4)
  // ---------------------------------------------------------------------
  wire [1:0] wr_idx    = wr_addr[3:2];
  wire       wr_mapped = (wr_addr[1:0] == 2'b00) &&
                         ((wr_addr >> 4) == {ADDR_WIDTH{1'b0}});

  wire [1:0] rd_idx    = s_axil_araddr[3:2];
  wire       rd_mapped = (s_axil_araddr[1:0] == 2'b00) &&
                         ((s_axil_araddr >> 4) == {ADDR_WIDTH{1'b0}});

  // ---------------------------------------------------------------------
  // Byte merge: merge(old, data, strb)
  // ---------------------------------------------------------------------
  wire [DATA_WIDTH-1:0] wr_old = (wr_idx == 2'd0) ? reg0_q :
                                 (wr_idx == 2'd1) ? reg1_q :
                                 (wr_idx == 2'd2) ? reg2_q : reg3_q;
  wire [DATA_WIDTH-1:0] wr_merged;

  genvar gi;
  generate
    for (gi = 0; gi < STRB_WIDTH; gi = gi + 1) begin : g_merge
      assign wr_merged[8*gi +: 8] = wr_strb[gi] ? wr_data[8*gi +: 8]
                                                : wr_old[8*gi +: 8];
    end
  endgenerate

  wire [DATA_WIDTH-1:0] rd_sel = (rd_idx == 2'd0) ? reg0_q :
                                 (rd_idx == 2'd1) ? reg1_q :
                                 (rd_idx == 2'd2) ? reg2_q : reg3_q;

  // ---------------------------------------------------------------------
  // Next-state logic
  // ---------------------------------------------------------------------
  // Held flags: set when one half arrives alone, cleared when the pair fires.
  always @* begin
    aw_held_d = aw_held_q;
    w_held_d  = w_held_q;
    if (do_write) begin
      aw_held_d = 1'b0;
      w_held_d  = 1'b0;
    end else begin
      if (aw_hs) begin
        aw_held_d = 1'b1;
      end
      if (w_hs) begin
        w_held_d = 1'b1;
      end
    end
  end

  // Write response
  always @* begin
    bvalid_d = bvalid_q;
    bresp_d  = bresp_q;
    if (bvalid_q && s_axil_bready) begin
      bvalid_d = 1'b0;
    end
    if (do_write) begin
      bvalid_d = 1'b1;
      bresp_d  = wr_mapped ? RESP_OKAY : RESP_SLVERR;
    end
  end

  // Read response: loaded on the edge that accepts AR
  always @* begin
    rvalid_d = rvalid_q;
    rresp_d  = rresp_q;
    rdata_d  = rdata_q;
    if (rvalid_q && s_axil_rready) begin
      rvalid_d = 1'b0;
    end
    if (ar_hs) begin
      rvalid_d = 1'b1;
      rresp_d  = rd_mapped ? RESP_OKAY : RESP_SLVERR;
      rdata_d  = rd_mapped ? rd_sel : {DATA_WIDTH{1'b0}};
    end
  end

  // Register file
  always @* begin
    reg0_d = reg0_q;
    reg1_d = reg1_q;
    reg2_d = reg2_q;
    reg3_d = reg3_q;
    if (do_write && wr_mapped) begin
      case (wr_idx)
        2'd0:    reg0_d = wr_merged;
        2'd1:    reg1_d = wr_merged;
        2'd2:    reg2_d = wr_merged;
        2'd3:    reg3_d = wr_merged;
        default: reg0_d = reg0_q;
      endcase
    end
  end

  // ---------------------------------------------------------------------
  // Registers
  // ---------------------------------------------------------------------
  always @(posedge aclk) begin
    if (!aresetn) begin
      aw_held_q <= 1'b0;
      w_held_q  <= 1'b0;
      bvalid_q  <= 1'b0;
      bresp_q   <= RESP_OKAY;
      rvalid_q  <= 1'b0;
      rresp_q   <= RESP_OKAY;
      rdata_q   <= {DATA_WIDTH{1'b0}};
      reg0_q    <= {DATA_WIDTH{1'b0}};
      reg1_q    <= {DATA_WIDTH{1'b0}};
      reg2_q    <= {DATA_WIDTH{1'b0}};
      reg3_q    <= {DATA_WIDTH{1'b0}};
    end else begin
      aw_held_q <= aw_held_d;
      w_held_q  <= w_held_d;
      bvalid_q  <= bvalid_d;
      bresp_q   <= bresp_d;
      rvalid_q  <= rvalid_d;
      rresp_q   <= rresp_d;
      rdata_q   <= rdata_d;
      reg0_q    <= reg0_d;
      reg1_q    <= reg1_d;
      reg2_q    <= reg2_d;
      reg3_q    <= reg3_d;
    end
  end

  // Holding registers: load enable only
  always @(posedge aclk) begin
    if (aw_hs) begin
      aw_addr_q <= s_axil_awaddr;
    end
    if (w_hs) begin
      w_data_q <= s_axil_wdata;
      w_strb_q <= s_axil_wstrb;
    end
  end

`ifdef FORMAL
  // ---------------------------------------------------------------------
  // Design-intent properties (microarchitecture.md section 7)
  // ---------------------------------------------------------------------
  reg f_past_valid;
  initial f_past_valid = 1'b0;
  always @(posedge aclk) f_past_valid <= 1'b1;

  // Reset on the first cycle
  always @(*) begin
    if (!f_past_valid) begin
      assume(!aresetn);
    end
  end

  // Manager rules (assumed): VALIDs low while reset is asserted
  always @(*) begin
    if (!aresetn) begin
      assume(!s_axil_awvalid);
      assume(!s_axil_wvalid);
      assume(!s_axil_arvalid);
    end
  end

  // Manager rules (assumed): VALID and its payload hold until READY
  always @(posedge aclk) begin
    if (f_past_valid && $past(aresetn) && aresetn) begin
      if ($past(s_axil_awvalid && !s_axil_awready)) begin
        assume(s_axil_awvalid);
        assume(s_axil_awaddr == $past(s_axil_awaddr));
      end
      if ($past(s_axil_wvalid && !s_axil_wready)) begin
        assume(s_axil_wvalid);
        assume(s_axil_wdata == $past(s_axil_wdata));
        assume(s_axil_wstrb == $past(s_axil_wstrb));
      end
      if ($past(s_axil_arvalid && !s_axil_arready)) begin
        assume(s_axil_arvalid);
        assume(s_axil_araddr == $past(s_axil_araddr));
      end
    end
  end

  // Subordinate rules (asserted)
  always @(posedge aclk) begin
    if (f_past_valid) begin
      if (!$past(aresetn)) begin
        assert(!s_axil_bvalid);
        assert(!s_axil_rvalid);
        assert(!aw_held_q);
        assert(!w_held_q);
      end else begin
        // B and R hold, with a stable payload, until taken
        if ($past(s_axil_bvalid && !s_axil_bready)) begin
          assert(s_axil_bvalid);
          assert(s_axil_bresp == $past(s_axil_bresp));
        end
        if ($past(s_axil_rvalid && !s_axil_rready)) begin
          assert(s_axil_rvalid);
          assert(s_axil_rresp == $past(s_axil_rresp));
          assert(s_axil_rdata == $past(s_axil_rdata));
        end
        // A response is high exactly when an accepted request awaits it
        assert(s_axil_bvalid == ($past(do_write) ||
                                 $past(s_axil_bvalid && !s_axil_bready)));
        assert(s_axil_rvalid == ($past(ar_hs) ||
                                 $past(s_axil_rvalid && !s_axil_rready)));
        // Response code follows the address policy
        if ($past(do_write)) begin
          assert(s_axil_bresp == ($past(wr_mapped) ? RESP_OKAY : RESP_SLVERR));
        end
        if ($past(ar_hs)) begin
          assert(s_axil_rresp == ($past(rd_mapped) ? RESP_OKAY : RESP_SLVERR));
          if (!$past(rd_mapped)) begin
            assert(s_axil_rdata == {DATA_WIDTH{1'b0}});
          end
        end
      end
    end
  end

  // At most one transaction outstanding per direction
  always @(*) begin
    if (f_past_valid) begin
      assert(!(aw_held_q && w_held_q));
      if (bvalid_q) begin
        assert(!aw_held_q);
        assert(!w_held_q);
      end
      assert((bresp_q == RESP_OKAY) || (bresp_q == RESP_SLVERR));
      assert((rresp_q == RESP_OKAY) || (rresp_q == RESP_SLVERR));
    end
  end

  // Covers
  always @(posedge aclk) begin
    if (f_past_valid && aresetn) begin
      cover(s_axil_bvalid && s_axil_bready && (s_axil_bresp == RESP_OKAY));
      cover(s_axil_bvalid && s_axil_bready && (s_axil_bresp == RESP_SLVERR));
      cover(s_axil_rvalid && s_axil_rready && (s_axil_rresp == RESP_OKAY));
      cover(s_axil_rvalid && s_axil_rready && (s_axil_rresp == RESP_SLVERR));
      cover(aw_held_q);
      cover(w_held_q);
    end
  end
`endif

endmodule

`default_nettype wire
=== END FILE ===
