`timescale 1ns / 1ps
`default_nettype none

// Self-checking directed testbench for axi4_lite_regs.
// Checks interface_spec.md section 8 and microarchitecture.md section 7.
// Inputs are driven on the falling edge; outputs are sampled 1 ns later
// (READY depends on state only), before the next rising edge.

`define CHECK(c, msg) begin if (c) passed = passed + 1; else begin failed = failed + 1; $error msg; end end

module axi4_lite_regs_tb;

  reg         aclk;
  reg         aresetn;
  reg  [3:0]  s_axil_awaddr;
  reg         s_axil_awvalid;
  wire        s_axil_awready;
  reg  [31:0] s_axil_wdata;
  reg  [3:0]  s_axil_wstrb;
  reg         s_axil_wvalid;
  wire        s_axil_wready;
  wire [1:0]  s_axil_bresp;
  wire        s_axil_bvalid;
  reg         s_axil_bready;
  reg  [3:0]  s_axil_araddr;
  reg         s_axil_arvalid;
  wire        s_axil_arready;
  wire [31:0] s_axil_rdata;
  wire [1:0]  s_axil_rresp;
  wire        s_axil_rvalid;
  reg         s_axil_rready;

  integer        passed;
  integer        failed;
  integer        i;
  reg [8*64-1:0] nonce;
  reg [31:0]     m [0:3];   // register model

  localparam [1:0] OKAY   = 2'b00;
  localparam [1:0] SLVERR = 2'b10;

  axi4_lite_regs #(
    .ADDR_WIDTH(4),
    .DATA_WIDTH(32)
  ) dut (
    .aclk           (aclk),
    .aresetn        (aresetn),
    .s_axil_awaddr  (s_axil_awaddr),
    .s_axil_awvalid (s_axil_awvalid),
    .s_axil_awready (s_axil_awready),
    .s_axil_wdata   (s_axil_wdata),
    .s_axil_wstrb   (s_axil_wstrb),
    .s_axil_wvalid  (s_axil_wvalid),
    .s_axil_wready  (s_axil_wready),
    .s_axil_bresp   (s_axil_bresp),
    .s_axil_bvalid  (s_axil_bvalid),
    .s_axil_bready  (s_axil_bready),
    .s_axil_araddr  (s_axil_araddr),
    .s_axil_arvalid (s_axil_arvalid),
    .s_axil_arready (s_axil_arready),
    .s_axil_rdata   (s_axil_rdata),
    .s_axil_rresp   (s_axil_rresp),
    .s_axil_rvalid  (s_axil_rvalid),
    .s_axil_rready  (s_axil_rready)
  );

  initial begin
    aclk = 1'b0;
    forever #5 aclk = ~aclk;
  end

  // ---------------------------------------------------------------------
  // Model helpers (from interface_spec.md sections 3 and 5)
  // ---------------------------------------------------------------------
  function is_mapped;
    input [3:0] a;
    begin
      is_mapped = (a[1:0] == 2'b00);
    end
  endfunction

  function [31:0] merge;
    input [31:0] old;
    input [31:0] data;
    input [3:0]  strb;
    integer k;
    begin
      merge = old;
      for (k = 0; k < 4; k = k + 1) begin
        if (strb[k]) begin
          merge[8*k +: 8] = data[8*k +: 8];
        end
      end
    end
  endfunction

  task idle_inputs;
    begin
      s_axil_awvalid = 1'b0;
      s_axil_awaddr  = 4'h0;
      s_axil_wvalid  = 1'b0;
      s_axil_wdata   = 32'h0;
      s_axil_wstrb   = 4'h0;
      s_axil_bready  = 1'b0;
      s_axil_arvalid = 1'b0;
      s_axil_araddr  = 4'h0;
      s_axil_rready  = 1'b0;
    end
  endtask

  // Synchronous reset for 'cycles' rising edges [req:AXIL-RESET]
  task do_reset;
    input integer cycles;
    integer k;
    begin
      @(negedge aclk);
      idle_inputs;
      aresetn = 1'b0;
      for (k = 0; k < cycles; k = k + 1) begin
        @(negedge aclk);
        #1;
        `CHECK(s_axil_bvalid == 1'b0, ("reset: BVALID high during reset"))
        `CHECK(s_axil_rvalid == 1'b0, ("reset: RVALID high during reset"))
      end
      for (k = 0; k < 4; k = k + 1) m[k] = 32'h0;
      `CHECK(s_axil_awready == 1'b1, ("reset: AWREADY low after reset"))
      `CHECK(s_axil_wready == 1'b1, ("reset: WREADY low after reset"))
      `CHECK(s_axil_arready == 1'b1, ("reset: ARREADY low after reset"))
      aresetn = 1'b1;
    end
  endtask

  // ---------------------------------------------------------------------
  // One optional write and one optional read, run together cycle by cycle.
  // aw_dly / w_dly / ar_dly: cycles before VALID rises.
  // b_dly / r_dly: 0 = READY high from the start; n = READY low for n
  // cycles after the response appears (back-pressure).
  // ---------------------------------------------------------------------
  task run;
    input         dw;
    input [3:0]   waddr;
    input [31:0]  wdata;
    input [3:0]   wstrb;
    input integer aw_dly;
    input integer w_dly;
    input integer b_dly;
    input         dr;
    input [3:0]   raddr;
    input integer ar_dly;
    input integer r_dly;
    integer t;
    integer wcomp;
    integer bseen;
    integer rcomp;
    integer rseen;
    reg aw_done;
    reg w_done;
    reg b_done;
    reg ar_done;
    reg r_done;
    reg aw_hs;
    reg w_hs;
    reg b_hs;
    reg ar_hs;
    reg r_hs;
    reg [1:0]  exp_bresp;
    reg [1:0]  exp_rresp;
    reg [31:0] exp_rdata;
    begin
      t = 0;
      wcomp = -1;
      bseen = -1;
      rcomp = -1;
      rseen = -1;
      aw_done = !dw;
      w_done  = !dw;
      b_done  = !dw;
      ar_done = !dr;
      r_done  = !dr;
      exp_bresp = OKAY;
      exp_rresp = OKAY;
      exp_rdata = 32'h0;
      while (!(b_done && r_done)) begin
        @(negedge aclk);
        // Drive; payload is junk whenever VALID is low
        s_axil_awvalid = !aw_done && (t >= aw_dly);
        s_axil_awaddr  = s_axil_awvalid ? waddr : ~waddr;
        s_axil_wvalid  = !w_done && (t >= w_dly);
        s_axil_wdata   = s_axil_wvalid ? wdata : ~wdata;
        s_axil_wstrb   = s_axil_wvalid ? wstrb : ~wstrb;
        s_axil_bready  = !b_done && ((b_dly == 0) || ((bseen >= 0) && (t >= bseen + b_dly)));
        s_axil_arvalid = !ar_done && (t >= ar_dly);
        s_axil_araddr  = s_axil_arvalid ? raddr : ~raddr;
        s_axil_rready  = !r_done && ((r_dly == 0) || ((rseen >= 0) && (t >= rseen + r_dly)));
        #1;

        // READY follows the transaction state
        if (!aw_done || b_done) begin
          `CHECK(s_axil_awready == 1'b1, ("t=%0d: AWREADY low with no write open", t))
        end else begin
          `CHECK(s_axil_awready == 1'b0, ("t=%0d: AWREADY high while a write is open", t))
        end
        if (!w_done || b_done) begin
          `CHECK(s_axil_wready == 1'b1, ("t=%0d: WREADY low with no write open", t))
        end else begin
          `CHECK(s_axil_wready == 1'b0, ("t=%0d: WREADY high while a write is open", t))
        end
        if (!ar_done || r_done) begin
          `CHECK(s_axil_arready == 1'b1, ("t=%0d: ARREADY low with no read open", t))
        end else begin
          `CHECK(s_axil_arready == 1'b0, ("t=%0d: ARREADY high while a read is open", t))
        end

        // Write response [req:AXIL-LATENCY]
        if ((wcomp < 0) || b_done) begin
          `CHECK(s_axil_bvalid == 1'b0, ("t=%0d: BVALID high with no write awaiting a response", t))
        end else begin
          if (bseen < 0) begin
            `CHECK((s_axil_bvalid == 1'b1) || ((t - wcomp) < 2), ("t=%0d: BVALID later than the 2-cycle bound", t))
            if (s_axil_bvalid) begin
              bseen = t;
              `CHECK((t - wcomp) == 1, ("t=%0d: B latency %0d, expected 1", t, t - wcomp))
            end
          end
          if (bseen >= 0) begin
            `CHECK(s_axil_bvalid == 1'b1, ("t=%0d: BVALID dropped before BREADY", t))
            `CHECK(s_axil_bresp == exp_bresp, ("t=%0d: BRESP %b, expected %b (addr %h)", t, s_axil_bresp, exp_bresp, waddr))
          end
        end

        // Read response [req:AXIL-LATENCY]
        if ((rcomp < 0) || r_done) begin
          `CHECK(s_axil_rvalid == 1'b0, ("t=%0d: RVALID high with no read awaiting data", t))
        end else begin
          if (rseen < 0) begin
            `CHECK((s_axil_rvalid == 1'b1) || ((t - rcomp) < 2), ("t=%0d: RVALID later than the 2-cycle bound", t))
            if (s_axil_rvalid) begin
              rseen = t;
              `CHECK((t - rcomp) == 1, ("t=%0d: R latency %0d, expected 1", t, t - rcomp))
            end
          end
          if (rseen >= 0) begin
            `CHECK(s_axil_rvalid == 1'b1, ("t=%0d: RVALID dropped before RREADY", t))
            `CHECK(s_axil_rresp == exp_rresp, ("t=%0d: RRESP %b, expected %b (addr %h)", t, s_axil_rresp, exp_rresp, raddr))
            `CHECK(s_axil_rdata == exp_rdata, ("t=%0d: RDATA %h, expected %h (addr %h)", t, s_axil_rdata, exp_rdata, raddr))
          end
        end

        // Handshakes taking effect at the coming rising edge
        aw_hs = s_axil_awvalid && s_axil_awready;
        w_hs  = s_axil_wvalid && s_axil_wready;
        b_hs  = s_axil_bvalid && s_axil_bready;
        ar_hs = s_axil_arvalid && s_axil_arready;
        r_hs  = s_axil_rvalid && s_axil_rready;

        // Model, step for step: a read samples the registers before a
        // write on the same edge updates them.
        if (ar_hs) begin
          ar_done   = 1'b1;
          rcomp     = t;
          exp_rresp = is_mapped(raddr) ? OKAY : SLVERR;
          exp_rdata = is_mapped(raddr) ? m[raddr[3:2]] : 32'h0;
        end
        if (aw_hs) aw_done = 1'b1;
        if (w_hs) w_done = 1'b1;
        if (dw && (wcomp < 0) && aw_done && w_done) begin
          wcomp     = t;
          exp_bresp = is_mapped(waddr) ? OKAY : SLVERR;
          if (is_mapped(waddr)) begin
            m[waddr[3:2]] = merge(m[waddr[3:2]], wdata, wstrb);
          end
        end
        if (b_hs) b_done = 1'b1;
        if (r_hs) r_done = 1'b1;

        t = t + 1;
        if (t > 64) begin
          `CHECK(1'b0, ("timeout: transaction did not complete"))
          b_done = 1'b1;
          r_done = 1'b1;
        end
      end
    end
  endtask

  task wr;
    input [3:0]   a;
    input [31:0]  d;
    input [3:0]   s;
    input integer aw_dly;
    input integer w_dly;
    input integer b_dly;
    begin
      run(1'b1, a, d, s, aw_dly, w_dly, b_dly, 1'b0, 4'h0, 0, 0);
    end
  endtask

  task rd;
    input [3:0]   a;
    input integer ar_dly;
    input integer r_dly;
    begin
      run(1'b0, 4'h0, 32'h0, 4'h0, 0, 0, 0, 1'b1, a, ar_dly, r_dly);
    end
  endtask

  task rd_all;
    begin
      rd(4'h0, 0, 0);
      rd(4'h4, 0, 0);
      rd(4'h8, 0, 0);
      rd(4'hC, 0, 0);
    end
  endtask

  // ---------------------------------------------------------------------
  // Watchdog: only reached if the main sequence hangs
  // ---------------------------------------------------------------------
  initial begin
    #1000000;
    $error("watchdog: simulation did not finish");
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed + 1);
    $finish;
  end

  // ---------------------------------------------------------------------
  // Main sequence
  // ---------------------------------------------------------------------
  initial begin
    passed = 0;
    failed = 0;
    nonce  = {64{8'h00}};
    if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = {64{8'h00}};
    aresetn = 1'b0;
    idle_inputs;
    for (i = 0; i < 4; i = i + 1) m[i] = 32'h0;

    // 1. Reset and reset values [req:AXIL-RESET]
    do_reset(3);
    rd_all;

    // 2. Write then read every register, AW and W together
    wr(4'h0, 32'h1122_3344, 4'hF, 0, 0, 0);
    wr(4'h4, 32'hA5A5_5A5A, 4'hF, 0, 0, 0);
    wr(4'h8, 32'hDEAD_BEEF, 4'hF, 0, 0, 0);
    wr(4'hC, 32'h0BAD_F00D, 4'hF, 0, 0, 0);
    rd_all;

    // 3. AW/W ordering [req:AXIL-ORDER]
    wr(4'h0, 32'hCAFE_0001, 4'hF, 0, 3, 0);  // AW 3 cycles before W
    wr(4'h4, 32'hCAFE_0002, 4'hF, 2, 0, 0);  // W 2 cycles before AW
    wr(4'h8, 32'hCAFE_0003, 4'hF, 1, 1, 0);  // together, after an idle cycle
    wr(4'hC, 32'hCAFE_0004, 4'hF, 0, 1, 0);  // AW 1 cycle before W
    wr(4'h0, 32'hCAFE_0005, 4'hF, 1, 0, 0);  // W 1 cycle before AW
    wr(4'h4, 32'hCAFE_0006, 4'hF, 0, 6, 2);  // long gap, then B stall
    wr(4'h8, 32'hCAFE_0007, 4'hF, 5, 0, 0);  // W long before AW
    rd_all;

    // 4. Byte strobes [req:AXIL-WSTRB]
    wr(4'h8, 32'hFFFF_FFFF, 4'hF, 0, 0, 0);
    wr(4'h8, 32'h0000_00AA, 4'b0001, 0, 0, 0);
    rd(4'h8, 0, 0);
    wr(4'h8, 32'h00BB_CC00, 4'b0110, 0, 2, 0);
    rd(4'h8, 0, 0);
    wr(4'h8, 32'h1200_0000, 4'b1000, 2, 0, 0);
    rd(4'h8, 0, 0);
    wr(4'h8, 32'h5555_5555, 4'b0000, 0, 0, 0);  // empty strobe: OKAY, no change
    rd(4'h8, 0, 0);
    wr(4'hC, 32'hA1B2_C3D4, 4'b0101, 0, 0, 0);
    rd(4'hC, 0, 0);
    wr(4'h0, 32'h9988_7766, 4'b1010, 3, 0, 1);
    rd(4'h0, 0, 0);

    // 5. Back-pressure on B and R
    wr(4'h4, 32'h55AA_55AA, 4'hF, 0, 0, 5);
    rd(4'h4, 0, 5);
    wr(4'h0, 32'h0123_4567, 4'hF, 0, 0, 1);
    rd(4'h0, 0, 1);
    rd(4'hC, 2, 3);

    // 5b. New write offered while B is stalled: it must wait
    @(negedge aclk);
    idle_inputs;
    s_axil_awvalid = 1'b1; s_axil_awaddr = 4'h0;
    s_axil_wvalid  = 1'b1; s_axil_wdata  = 32'h0101_0101; s_axil_wstrb = 4'hF;
    #1;
    `CHECK(s_axil_awready && s_axil_wready, ("B stall test: AW/W not ready when idle"))
    m[0] = 32'h0101_0101;
    @(negedge aclk);
    s_axil_awaddr = 4'h4; s_axil_wdata = 32'h0202_0202;  // next write offered
    #1;
    `CHECK(s_axil_bvalid == 1'b1, ("B stall test: BVALID not raised"))
    `CHECK(s_axil_bresp == OKAY, ("B stall test: BRESP not OKAY"))
    `CHECK(s_axil_awready == 1'b0, ("B stall test: AWREADY high while B stalled"))
    `CHECK(s_axil_wready == 1'b0, ("B stall test: WREADY high while B stalled"))
    @(negedge aclk);
    #1;
    `CHECK(s_axil_bvalid == 1'b1, ("B stall test: BVALID dropped while stalled"))
    `CHECK(s_axil_bresp == OKAY, ("B stall test: BRESP changed while stalled"))
    `CHECK(s_axil_awready == 1'b0, ("B stall test: AWREADY high while B stalled (2)"))
    `CHECK(s_axil_wready == 1'b0, ("B stall test: WREADY high while B stalled (2)"))
    @(negedge aclk);
    s_axil_bready = 1'b1;
    #1;
    `CHECK(s_axil_bvalid == 1'b1, ("B stall test: BVALID low at BREADY"))
    `CHECK(s_axil_awready == 1'b0, ("B stall test: AWREADY high before B taken"))
    @(negedge aclk);
    s_axil_bready = 1'b0;
    #1;
    `CHECK(s_axil_bvalid == 1'b0, ("B stall test: BVALID high after B taken"))
    `CHECK(s_axil_awready && s_axil_wready, ("B stall test: AW/W not ready after B taken"))
    m[1] = 32'h0202_0202;
    @(negedge aclk);
    s_axil_awvalid = 1'b0; s_axil_wvalid = 1'b0; s_axil_bready = 1'b1;
    #1;
    `CHECK(s_axil_bvalid == 1'b1, ("B stall test: second write got no B"))
    `CHECK(s_axil_bresp == OKAY, ("B stall test: second BRESP not OKAY"))
    @(negedge aclk);
    idle_inputs;
    #1;
    `CHECK(s_axil_bvalid == 1'b0, ("B stall test: extra B"))

    // 5c. New read offered while R is stalled: it must wait
    @(negedge aclk);
    idle_inputs;
    s_axil_arvalid = 1'b1; s_axil_araddr = 4'h0;
    #1;
    `CHECK(s_axil_arready == 1'b1, ("R stall test: ARREADY low when idle"))
    @(negedge aclk);
    s_axil_araddr = 4'h4;  // next read offered
    #1;
    `CHECK(s_axil_rvalid == 1'b1, ("R stall test: RVALID not raised"))
    `CHECK(s_axil_rdata == m[0], ("R stall test: RDATA %h, expected %h", s_axil_rdata, m[0]))
    `CHECK(s_axil_rresp == OKAY, ("R stall test: RRESP not OKAY"))
    `CHECK(s_axil_arready == 1'b0, ("R stall test: ARREADY high while R stalled"))
    @(negedge aclk);
    #1;
    `CHECK(s_axil_rvalid == 1'b1, ("R stall test: RVALID dropped while stalled"))
    `CHECK(s_axil_rdata == m[0], ("R stall test: RDATA changed while stalled"))
    `CHECK(s_axil_arready == 1'b0, ("R stall test: ARREADY high while R stalled (2)"))
    @(negedge aclk);
    s_axil_rready = 1'b1;
    #1;
    `CHECK(s_axil_rvalid == 1'b1, ("R stall test: RVALID low at RREADY"))
    `CHECK(s_axil_arready == 1'b0, ("R stall test: ARREADY high before R taken"))
    @(negedge aclk);
    s_axil_rready = 1'b0;
    #1;
    `CHECK(s_axil_rvalid == 1'b0, ("R stall test: RVALID high after R taken"))
    `CHECK(s_axil_arready == 1'b1, ("R stall test: ARREADY low after R taken"))
    @(negedge aclk);
    s_axil_arvalid = 1'b0; s_axil_rready = 1'b1;
    #1;
    `CHECK(s_axil_rvalid == 1'b1, ("R stall test: second read got no R"))
    `CHECK(s_axil_rdata == m[1], ("R stall test: second RDATA %h, expected %h", s_axil_rdata, m[1]))
    @(negedge aclk);
    idle_inputs;
    #1;
    `CHECK(s_axil_rvalid == 1'b0, ("R stall test: extra R"))

    // 6. Back-to-back transactions [req:AXIL-B2B]
    for (i = 0; i < 4; i = i + 1) begin
      wr({i[1:0], 2'b00}, 32'hB2B0_0000 + i, 4'hF, 0, 0, 0);
    end
    for (i = 0; i < 4; i = i + 1) begin
      rd({i[1:0], 2'b00}, 0, 0);
    end
    for (i = 0; i < 4; i = i + 1) begin
      run(1'b1, {i[1:0], 2'b00}, 32'hB2C0_0000 + i, 4'hF, 0, 0, 0,
          1'b1, {~i[1:0], 2'b00}, 0, 0);
    end
    rd_all;

    // 7. SLVERR policy for unmapped (misaligned) addresses [req:AXIL-SLVERR]
    wr(4'h5, 32'hDEAD_0005, 4'hF, 0, 0, 0);
    wr(4'h6, 32'hDEAD_0006, 4'hF, 2, 0, 0);
    wr(4'h3, 32'hDEAD_0003, 4'hF, 0, 2, 0);
    wr(4'hE, 32'hDEAD_000E, 4'b0000, 0, 0, 0);
    wr(4'hF, 32'hDEAD_000F, 4'hF, 0, 0, 3);
    wr(4'h1, 32'hDEAD_0001, 4'b0011, 1, 1, 0);
    rd(4'h1, 0, 0);
    rd(4'h2, 0, 2);
    rd(4'h7, 0, 0);
    rd(4'hE, 0, 0);
    rd(4'hF, 1, 0);
    rd_all;  // unmapped writes changed nothing

    // 8. Reads and writes in flight together
    run(1'b1, 4'hC, 32'h7777_0000, 4'hF, 0, 0, 0, 1'b1, 4'h0, 0, 0);  // same cycle, different registers
    run(1'b1, 4'h4, 32'h4444_4444, 4'hF, 0, 0, 0, 1'b1, 4'h4, 0, 0);  // same cycle, same register
    rd(4'h4, 0, 0);
    run(1'b1, 4'h8, 32'h8888_8888, 4'hF, 0, 2, 3, 1'b1, 4'h8, 3, 2);  // read after the write completes
    run(1'b1, 4'h5, 32'h0000_0000, 4'hF, 1, 0, 2, 1'b1, 4'hD, 0, 3);  // both unmapped, stalled
    run(1'b1, 4'h0, 32'h0F0F_0F0F, 4'b0011, 3, 1, 0, 1'b1, 4'hC, 1, 0);
    run(1'b1, 4'hC, 32'hC0C0_C0C0, 4'hF, 0, 4, 1, 1'b1, 4'h6, 2, 4);
    rd_all;

    // 9. Reset during traffic [req:AXIL-RESET]
    // 9a. AW accepted without W, then reset: the held address is dropped
    @(negedge aclk);
    idle_inputs;
    s_axil_awvalid = 1'b1; s_axil_awaddr = 4'h4;
    #1;
    `CHECK(s_axil_awready == 1'b1, ("reset 9a: AWREADY low before AW"))
    @(negedge aclk);
    idle_inputs;
    #1;
    `CHECK(s_axil_awready == 1'b0, ("reset 9a: AW not held"))
    `CHECK(s_axil_wready == 1'b1, ("reset 9a: WREADY low with only AW held"))
    `CHECK(s_axil_bvalid == 1'b0, ("reset 9a: BVALID without W"))
    do_reset(1);
    wr(4'h8, 32'h8888_0001, 4'hF, 2, 0, 0);  // lone W first must not pair with the dropped AW
    rd_all;

    // 9b. W accepted without AW, then reset: the held data is dropped
    @(negedge aclk);
    idle_inputs;
    s_axil_wvalid = 1'b1; s_axil_wdata = 32'hBAD0_BAD0; s_axil_wstrb = 4'hF;
    #1;
    `CHECK(s_axil_wready == 1'b1, ("reset 9b: WREADY low before W"))
    @(negedge aclk);
    idle_inputs;
    #1;
    `CHECK(s_axil_wready == 1'b0, ("reset 9b: W not held"))
    `CHECK(s_axil_awready == 1'b1, ("reset 9b: AWREADY low with only W held"))
    `CHECK(s_axil_bvalid == 1'b0, ("reset 9b: BVALID without AW"))
    do_reset(1);
    wr(4'hC, 32'hC0DE_000C, 4'hF, 0, 2, 0);  // lone AW first must wait for its own W
    rd_all;

    // 9c. Reset while B and R are pending
    wr(4'h0, 32'h1111_1111, 4'hF, 0, 0, 0);
    wr(4'h8, 32'h2222_2222, 4'hF, 0, 0, 0);
    @(negedge aclk);
    idle_inputs;
    s_axil_awvalid = 1'b1; s_axil_awaddr = 4'h4;
    s_axil_wvalid  = 1'b1; s_axil_wdata  = 32'h3333_3333; s_axil_wstrb = 4'hF;
    s_axil_arvalid = 1'b1; s_axil_araddr = 4'h8;
    #1;
    `CHECK(s_axil_awready && s_axil_wready && s_axil_arready, ("reset 9c: not ready when idle"))
    m[1] = 32'h3333_3333;
    @(negedge aclk);
    idle_inputs;
    #1;
    `CHECK(s_axil_bvalid == 1'b1, ("reset 9c: BVALID not raised"))
    `CHECK(s_axil_rvalid == 1'b1, ("reset 9c: RVALID not raised"))
    `CHECK(s_axil_rdata == m[2], ("reset 9c: RDATA %h, expected %h", s_axil_rdata, m[2]))
    @(negedge aclk);
    #1;
    `CHECK(s_axil_bvalid == 1'b1, ("reset 9c: BVALID dropped while stalled"))
    `CHECK(s_axil_rvalid == 1'b1, ("reset 9c: RVALID dropped while stalled"))
    do_reset(1);
    rd_all;

    // 10. Every register written and read back after reset
    wr(4'h0, 32'hF00D_0000, 4'hF, 0, 0, 0);
    wr(4'h4, 32'hF00D_0004, 4'hF, 1, 0, 1);
    wr(4'h8, 32'hF00D_0008, 4'hF, 0, 1, 0);
    wr(4'hC, 32'hF00D_000C, 4'hF, 0, 0, 2);
    rd_all;

    @(negedge aclk);
    idle_inputs;
    repeat (2) @(negedge aclk);
    `CHECK(passed > 0, ("no check passed"))
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end

endmodule

`undef CHECK
`default_nettype wire
